85	// select a user page to write to disk (NRU), returns pa
86	ptr_t selete_page()
87	{
88	    /* NRU (clock) algorithm: give recently accessed pages a second
89	     * chance by clearing their _PAGE_ACCESSED bit, and select the
90	     * first valid, unpinned page whose accessed bit is 0 */
91	    static int clock_hand = 0;
92	    while(1){
93	        int i = clock_hand;
94	        clock_hand = (clock_hand + 1) % USER_PAGE_NUM;
95	        if(user_page[i].valid == 0 || user_page[i].pin != 0){
96	            continue;
97	        }
98	        PTE *pte = user_page[i].pgtable;
99	        if(pte == NULL){
100	            continue;
101	        }
102	        if(get_attribute(*pte, _PAGE_ACCESSED)){
103	            clear_attribute(pte, _PAGE_ACCESSED);
104	            continue;
105	        }
106	        return num2pa(i);
107	    }
108	}
