110	void write_to_sd(ptr_t pa)
111	{
112	    /* find a free slot in the swap area */
113	    int i;
114	    for(i = 0; i < DISK_PAGE_NUM; i++){
115	        if(disk_page[i].valid == 0){
116	            break;
117	        }
118	    }
119	    assert(i != DISK_PAGE_NUM);
120	    disk_page[i].valid = 1;
121	
122	    /* one page = 8 sd blocks(512B), swap area starts at SWAP_BEGIN */
123	    sbi_sd_write((unsigned int)pa, PAGE_SIZE / 512,
124	                 SWAP_BEGIN + i * (PAGE_SIZE / 512));
125	
126	    /* mark the owner's pte as swapped out: clear _PAGE_PRESENT,
127	     * set _PAGE_SOFT and record the disk slot number in pfn */
128	    PTE *pte = user_page[pa2num(pa)].pgtable;
129	    if(pte != NULL){
130	        clear_attribute(pte, _PAGE_PRESENT);
131	        set_attribute(pte, _PAGE_SOFT);
132	        set_pfn(pte, i);
133	    }
134	
135	    /* the physical page is free now */
136	    user_page[pa2num(pa)].valid = 0;
137	    flush_tlb_all();
138	}
