155	/*
156	 * walk the 3-level sv39 page table (pgdir is pa) for `va`;
157	 * when `alloc` is non-zero, missing intermediate levels are
158	 * allocated from the pgdir page pool.
159	 * returns the kva of the leaf pte, or NULL if not present.
160	 */
161	static PTE *get_leaf_pte(uintptr_t va, PTE *pgdir, int alloc)
162	{
163	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
164	    uint64_t vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
165	    uint64_t vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
166	    uint64_t vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;
167	
168	    if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
169	        if(!alloc){
170	            return NULL;
171	        }
172	        PTE *new_pgdir = alloc_pgdir_page();
173	        set_pfn(&pgdir_kva[vpn2], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
174	        set_attribute(&pgdir_kva[vpn2], _PAGE_PRESENT);
175	    }
176	    PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));
177	
178	    if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
179	        if(!alloc){
180	            return NULL;
181	        }
182	        PTE *new_pgdir = alloc_pgdir_page();
183	        set_pfn(&second_kva[vpn1], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
184	        set_attribute(&second_kva[vpn1], _PAGE_PRESENT);
185	    }
186	    PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[vpn1]));
187	
188	    return &last_kva[vpn0];
189	}
