191	/*
192	 * Virtual Memory Layout
193	 * 0x0_0000_1000 ~ 0x0_0001_0000: share
194	 * 0x0_0001_0000 ~ 0x0_0001_3000: code
195	 * 0xf_0000_f000 ~ 0xf_0001_0000: stack
196	 */
197	PTE* init_page_table()
198	{
199	    PTE *pgdir = alloc_pgdir_page();
200	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
201	
202	    /* share the kernel mapping (kva area) with the kernel page table,
203	     * so that the kernel is mapped in every process's address space */
204	    PTE *kernel_pgdir = (PTE *)pa2kva(PGDIR_PA);
205	    pgdir_kva[0x101] = kernel_pgdir[0x101];
206	
207	    /* pre-allocate and map the user code region, so that load_elf()
208	     * can copy the segments through get_kva_of() */
209	    for(uintptr_t va = USER_CODE_BEGIN; va < USER_CODE_END; va += PAGE_SIZE){
210	        PTE *leaf = get_leaf_pte(va, pgdir, 1);
211	        ptr_t pa = alloc_user_page(0, leaf);
212	        clear_pgdir((PTE *)pa2kva(pa));
213	        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
214	        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
215	                            _PAGE_EXEC | _PAGE_USER |
216	                            _PAGE_ACCESSED | _PAGE_DIRTY);
217	    }
218	
219	    return pgdir;
220	}
