222	void free_process_user_page(PTE* pgdir)
223	{
224	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
225	    for(int i = 0; i < NUM_PTE_ENTRY; i++){
226	        if(!get_attribute(pgdir_kva[i], _PAGE_PRESENT)){
227	            continue;
228	        }
229	        if(i == 0x101){
230	            /* the kernel mapping is shared, do not free it */
231	            continue;
232	        }
233	        PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[i]));
234	        for(int j = 0; j < NUM_PTE_ENTRY; j++){
235	            if(!get_attribute(second_kva[j], _PAGE_PRESENT)){
236	                continue;
237	            }
238	            PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[j]));
239	            for(int k = 0; k < NUM_PTE_ENTRY; k++){
240	                uintptr_t va = ((uintptr_t)i << VPN2_SHIFT) |
241	                               ((uintptr_t)j << VPN1_SHIFT) |
242	                               ((uintptr_t)k << VPN0_SHIFT);
243	                if(get_attribute(last_kva[k], _PAGE_SOFT)){
244	                    /* the page is in the swap area, free the disk slot */
245	                    disk_page[get_pfn(last_kva[k])].valid = 0;
246	                    continue;
247	                }
248	                if(!get_attribute(last_kva[k], _PAGE_PRESENT)){
249	                    continue;
250	                }
251	                uintptr_t pa = get_pa(last_kva[k]);
252	                if(va >= SHM_BASE && va < USER_CODE_BEGIN){
253	                    /* shared page: only freed when the last user detaches */
254	                    int key = (va - SHM_BASE) / PAGE_SIZE;
255	                    shm_page[key].count--;
256	                    if(shm_page[key].count == 0){
257	                        free_user_page(pa);
258	                        shm_page[key].pa = 0;
259	                    }
260	                }
261	                else{
262	                    free_user_page(pa);
263	                }
264	            }
265	            free_pgdir_page(kva2pa((uintptr_t)last_kva));
266	        }
267	        free_pgdir_page(kva2pa((uintptr_t)second_kva));
268	    }
269	    free_pgdir_page((uintptr_t)pgdir);
270	}
