272	uintptr_t shm_page_get(int key)
273	{
274	    if(key < 0 || key >= SHM_PAGE_NUM){
275	        return 0;
276	    }
277	    uintptr_t va = SHM_BASE + key * PAGE_SIZE;
278	    PTE *pgdir = current_running[cpu_id]->pgdir;
279	    PTE *leaf = get_leaf_pte(va, pgdir, 1);
280	
281	    if(shm_page[key].count == 0){
282	        /* first user: allocate the physical shared page */
283	        uintptr_t pa = alloc_user_page(1, NULL);
284	        clear_pgdir((PTE *)pa2kva(pa));
285	        shm_page[key].pa = pa;
286	    }
287	    shm_page[key].count++;
288	
289	    set_pfn(leaf, shm_page[key].pa >> NORMAL_PAGE_SHIFT);
290	    set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
291	                        _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
292	    local_flush_tlb_all();
293	    return va;
294	}
