296	void shm_page_dt(uintptr_t addr)
297	{
298	    int key = (addr - SHM_BASE) / PAGE_SIZE;
299	    if(key < 0 || key >= SHM_PAGE_NUM){
300	        return;
301	    }
302	    PTE *pgdir = current_running[cpu_id]->pgdir;
303	    PTE *leaf = get_leaf_pte(addr, pgdir, 0);
304	    if(leaf != NULL){
305	        *leaf = 0;
306	    }
307	    local_flush_tlb_all();
308	
309	    shm_page[key].count--;
310	    if(shm_page[key].count <= 0){
311	        shm_page[key].count = 0;
312	        free_user_page(shm_page[key].pa);
313	        shm_page[key].pa = 0;
314	    }
315	}
