317	void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
318	{
319	    /* kernel must not page fault */
320	    if(stval >= KERNEL_MEM_OFFSET){
321	        handle_other(regs, stval, cause);
322	        return;
323	    }
324	
325	    uintptr_t va = stval & VA_MASK;
326	    PTE *pgdir = current_running[cpu_id]->pgdir;
327	    PTE *leaf = get_leaf_pte(va, pgdir, 1);
328	
329	    if(get_attribute(*leaf, _PAGE_SOFT)){
330	        /* the page was swapped out: swap it back in */
331	        int slot = get_pfn(*leaf);
332	        ptr_t pa = alloc_user_page(0, leaf);
333	        sbi_sd_read((unsigned int)pa, PAGE_SIZE / 512,
334	                    SWAP_BEGIN + slot * (PAGE_SIZE / 512));
335	        disk_page[slot].valid = 0;
336	        clear_attribute(leaf, _PAGE_SOFT);
337	        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
338	        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
339	                            _PAGE_EXEC | _PAGE_USER |
340	                            _PAGE_ACCESSED | _PAGE_DIRTY);
341	    }
342	    else if(!get_attribute(*leaf, _PAGE_PRESENT)){
343	        /* demand paging: allocate a fresh, zeroed page */
344	        ptr_t pa = alloc_user_page(0, leaf);
345	        clear_pgdir((PTE *)pa2kva(pa));
346	        set_pfn(leaf, pa >> NORMAL_PAGE_SHIFT);
347	        set_attribute(leaf, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
348	                            _PAGE_EXEC | _PAGE_USER |
349	                            _PAGE_ACCESSED | _PAGE_DIRTY);
350	    }
351	
352	    local_flush_tlb_all();
353	    /* return without advancing sepc: re-execute the faulting instruction */
354	}

