135	static inline uintptr_t kva2pa(uintptr_t kva)
136	{
137	    return (uintptr_t)(kva - KERNEL_MEM_OFFSET);
138	}
139	static inline uintptr_t pa2kva(uintptr_t pa)
140	{
141	    return (uintptr_t)(pa + KERNEL_MEM_OFFSET);
142	}
