35	/* 
36	 * Only modify PCB, current_running, process_id and ready_queue
37	 * DO NOT STORE OR RESTORE 
38	 * trick: modify $tp in ret_from_exception to ensure
39	 * disable_preempt() and enable_preempt() modify the same PCB
40	 */
41	void scheduler(void)
42	{
43	    /* pick the next task before requeueing the current one, so that
44	     * the current task can keep running when nothing else is ready */
45	    list_node_t *next_node = max_priority_node();
46	    if(next_node == NULL){
47	        return;
48	    }
49	
50	    pcb_t *cur_running = current_running[cpu_id];
51	    if(cur_running->status == TASK_RUNNING){
52	        cur_running->status = TASK_READY;
53	        cur_running->ready_tick = get_ticks();
54	        list_add_tail(&cur_running->list, &ready_queue);
55	    }
56	
57	    pcb_t *next_running = list_entry(next_node, pcb_t, list);
58	    list_del(next_node);
59	    next_running->status = TASK_RUNNING;
60	    next_running->cpu_id = cpu_id;
61	
62	    current_running[cpu_id] = next_running;
63	    /* ret_from_exception() switches to $tp = current_cpu_running */
64	    current_cpu_running = next_running;
65	
66	    /* switch the address space */
67	    set_satp(SATP_MODE_SV39, 0,
68	             ((uintptr_t)next_running->pgdir) >> NORMAL_PAGE_SHIFT);
69	    local_flush_tlb_all();
70	}
