72	/*
73	 * walk the 3-level sv39 page table (pgdir is pa) for `va`,
74	 * allocating missing intermediate levels from the pgdir page pool;
75	 * returns the kva of the leaf pte.
76	 */
77	static PTE *walk_pgtable(uintptr_t va, PTE *pgdir)
78	{
79	    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
80	    uint64_t vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
81	    uint64_t vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
82	    uint64_t vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;
83	
84	    if(!get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)){
85	        PTE *new_pgdir = alloc_pgdir_page();
86	        set_pfn(&pgdir_kva[vpn2], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
87	        set_attribute(&pgdir_kva[vpn2], _PAGE_PRESENT);
88	    }
89	    PTE *second_kva = (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));
90	
91	    if(!get_attribute(second_kva[vpn1], _PAGE_PRESENT)){
92	        PTE *new_pgdir = alloc_pgdir_page();
93	        set_pfn(&second_kva[vpn1], (uintptr_t)new_pgdir >> NORMAL_PAGE_SHIFT);
94	        set_attribute(&second_kva[vpn1], _PAGE_PRESENT);
95	    }
96	    PTE *last_kva = (PTE *)pa2kva(get_pa(second_kva[vpn1]));
97	
98	    return &last_kva[vpn0];
99	}
