101	pid_t do_exec(const char* file_name, int argc, char* argv[], spawn_mode_t mode)
102	{
103	    /* find a free pcb */
104	    int i;
105	    for(i = 0; i < NUM_MAX_TASK; i++){
106	        if(pcb[i].pid == -1){
107	            break;
108	        }
109	    }
110	    if(i == NUM_MAX_TASK){
111	        return 0;    /* too many tasks */
112	    }
113	
114	    /* the arguments live in the caller's address space */
115	    enable_sum();
116	
117	    /* find the elf file */
118	    unsigned char *binary = NULL;
119	    int length = 0;
120	    if(get_elf_file(file_name, &binary, &length) == 0){
121	        disable_sum();
122	        return -1;   /* no such process */
123	    }
124	
125	    /* copy the arguments into a kernel buffer */
126	    char arg_buf[16][100];
127	    if(argc > 16){
128	        argc = 16;
129	    }
130	    for(int j = 0; j < argc; j++){
131	        strcpy(arg_buf[j], argv[j]);
132	    }
133	    disable_sum();
134	
135	    /* initialize the pcb (mirrors init_pcb() in main.c) */
136	    pcb[i].kernel_sp = pa2kva(alloc_user_page(1, NULL) + PAGE_SIZE);
137	    pcb[i].user_sp = USER_STACK_ADDR;
138	    pcb[i].preempt_count = 0;
139	    pcb[i].kernel_stack_base = pcb[i].kernel_sp;
140	    pcb[i].user_stack_base = pcb[i].user_sp;
141	    list_add_tail(&pcb[i].list, &ready_queue);
142	    init_list_head(&pcb[i].wait_list);
143	    pcb[i].binsem_num = 0;
144	    pcb[i].pid = process_id++;
145	    pcb[i].type = USER_PROCESS;
146	    pcb[i].status = TASK_READY;
147	    pcb[i].mode = mode;
148	    pcb[i].priority = 0;
149	    pcb[i].ready_tick = get_ticks();
150	    pcb[i].mask = 3;
151	    pcb[i].cpu_id = cpu_id;
152	    pcb[i].pgdir = init_page_table();
153	
154	    /* load the elf segments into the new address space */
155	    uintptr_t entry = load_elf(binary, length, (uintptr_t)pcb[i].pgdir, get_kva_of);
156	
157	    /* allocate and map one page for the user stack */
158	    PTE *stack_pte = walk_pgtable(USER_STACK_ADDR - PAGE_SIZE, pcb[i].pgdir);
159	    ptr_t stack_pa = alloc_user_page(0, stack_pte);
160	    clear_pgdir((PTE *)pa2kva(stack_pa));
161	    set_pfn(stack_pte, stack_pa >> NORMAL_PAGE_SHIFT);
162	    set_attribute(stack_pte, _PAGE_PRESENT | _PAGE_READ | _PAGE_WRITE |
163	                             _PAGE_USER | _PAGE_ACCESSED | _PAGE_DIRTY);
164	
165	    /* push the argument strings on the top of the user stack */
166	    uintptr_t user_sp = USER_STACK_ADDR;
167	    uintptr_t stack_kva = pa2kva(stack_pa) + PAGE_SIZE;
168	    uintptr_t arg_va[16];
169	    for(int j = 0; j < argc; j++){
170	        int len = strlen(arg_buf[j]) + 1;
171	        user_sp -= len;
172	        stack_kva -= len;
173	        strcpy((char *)stack_kva, arg_buf[j]);
174	        arg_va[j] = user_sp;
175	    }
176	    /* push the argv pointer array */
177	    user_sp = ROUNDDOWN(user_sp, sizeof(uintptr_t));
178	    stack_kva = ROUNDDOWN(stack_kva, sizeof(uintptr_t));
179	    user_sp -= argc * sizeof(uintptr_t);
180	    stack_kva -= argc * sizeof(uintptr_t);
181	    memcpy((uint8_t *)stack_kva, (uint8_t *)arg_va, argc * sizeof(uintptr_t));
182	    uintptr_t argv_user = user_sp;
183	    /* sp must be 16-byte aligned at entry */
184	    user_sp = ROUNDDOWN(user_sp, 16);
185	
186	    /* initialize the register context on the kernel stack
187	     * (mirrors init_pcb_stack() in main.c) */
188	    regs_context_t *pt_regs = (regs_context_t *)(pcb[i].kernel_sp - sizeof(regs_context_t));
189	    pcb[i].kernel_sp -= sizeof(regs_context_t);
190	    pt_regs->regs[1] = (reg_t)entry;            // ra
191	    pt_regs->regs[2] = (reg_t)user_sp;          // sp
192	    pt_regs->regs[3] = (reg_t)__global_pointer$;// gp
193	    pt_regs->regs[10] = (reg_t)argc;            // a0
194	    pt_regs->regs[11] = (reg_t)argv_user;       // a1
195	    pt_regs->sstatus = (reg_t)SR_SPIE;          // SPP = 0, SPIE = 1
196	    pt_regs->sepc = (reg_t)entry;               // sepc
197	    pt_regs->sscratch = (reg_t)&pcb[i];         // sscratch = tp
198	
199	    return pcb[i].pid;
200	}
