202	/* release all the binsem locks acquired by `p` */
203	static void release_binsem(pcb_t *p)
204	{
205	    for(int i = 0; i < p->binsem_num; i++){
206	        int binsem_id = p->binsem_id[i];
207	        binsem_nodes[binsem_id].sem++;
208	        if(binsem_nodes[binsem_id].sem <= 0){
209	            list_node_t *unblocked_node = binsem_nodes[binsem_id].block_queue.next;
210	            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
211	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
212	            unblocked_pcb->binsem_num++;
213	            do_unblock(unblocked_node);
214	        }
215	    }
216	    p->binsem_num = 0;
217	}
