219	void do_exit()
220	{
221	    pcb_t *exit_pcb = current_running[cpu_id];
222	
223	    /* release the acquired binsem locks */
224	    release_binsem(exit_pcb);
225	
226	    /* release the address space: user pages, swap slots and page table */
227	    free_process_user_page(exit_pcb->pgdir);
228	
229	    /* wake up the processes waiting for this one */
230	    while(!list_empty(&exit_pcb->wait_list)){
231	        do_unblock(exit_pcb->wait_list.next);
232	    }
233	
234	    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
235	        /* keep the pcb so that do_waitpid() can find and reap it */
236	        exit_pcb->status = TASK_ZOMBIE;
237	    }
238	    else{
239	        /* hand over to the reaper in main(): it releases the pcb
240	         * and the kernel stack (we are still running on it) */
241	        exit_pcb->status = TASK_EXITED;
242	        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
243	    }
244	
245	    scheduler();
246	}
