248	// sleep(seconds)
249	void do_sleep(uint32_t sleep_time)
250	{
251	    // 1. block the current_running
252	    // 2. create a timer which calls `do_unblock` when timeout
253	    // 3. reschedule because the current_running is blocked
254	    do_block(&current_running[cpu_id]->list, &sleep_queue);
255	    list_node_t* parameter = &current_running[cpu_id]->list;
256	    timer_create((TimerCallback)do_unblock, (void*)parameter, get_ticks() + time_base * sleep_time);
257	    scheduler();
258	}
