307	int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
308	{
309	    while(1){
310	        /* search the pcb */
311	        pcb_t *wait_pcb = NULL;
312	        for(int i = 0; i < NUM_MAX_TASK; i++){
313	            if(pcb[i].pid == pid){
314	                wait_pcb = &pcb[i];
315	                break;
316	            }
317	        }
318	        if(wait_pcb == NULL){
319	            return -1;
320	        }
321	
322	        if(wait_pcb->status == TASK_ZOMBIE){
323	            /* reap the zombie: release its kernel stack and pcb */
324	            free_user_page(kva2pa(wait_pcb->kernel_stack_base - PAGE_SIZE));
325	            wait_pcb->status = TASK_EXITED;
326	            wait_pcb->pid = -1;
327	            return pid;
328	        }
329	        if(wait_pcb->status == TASK_EXITED){
330	            return pid;
331	        }
332	
333	        /* block until the target process exits */
334	        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
335	        scheduler();
336	    }
337	}
