515	// unblock the `pcb` from the block queue
516	void do_unblock(list_node_t *pcb_node)
517	{
518	    list_del(pcb_node);
519	    list_add_tail(pcb_node, &ready_queue);
520	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
521	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
522	}
523	
524	list_node_t* max_priority_node(void)
525	{
526	    /* choose the ready task with the highest priority that is allowed
527	     * to run on this core; ties are broken by the earliest ready_tick
528	     * (first-come-first-served) */
529	    list_node_t *best = NULL;
530	    unsigned long cpu_mask = 1lu << cpu_id;
531	    list_node_t *node = ready_queue.next;
532	    while(node != &ready_queue){
533	        pcb_t *p = list_entry(node, pcb_t, list);
534	        if(p->mask & cpu_mask){
535	            if(best == NULL){
536	                best = node;
537	            }
538	            else{
539	                pcb_t *b = list_entry(best, pcb_t, list);
540	                if(p->priority > b->priority ||
541	                   (p->priority == b->priority && p->ready_tick < b->ready_tick)){
542	                    best = node;
543	                }
544	            }
545	        }
546	        node = node->next;
547	    }
548	    return best;
549	}

