161	// jump from start.S
162	// The beginning of everything
163	int main()
164	{   
165	    // read CPU frequency and calc timer interval
166	    time_base = sbi_read_fdt(TIMEBASE);
167	    timer_interval = (uint64_t)(time_base / 100);
168	
169	    // init Process Control Block
170	    init_pcb();
171	    printk("> [INIT] PCB Initialization Succeeded.\n\r");
172	
173	    // init futex mechanism and binsem mechanism
174	    init_system_futex();
175	    init_system_binsem();
176	
177	    // init interrupt
178	    init_exception();
179	    printk("> [INIT] Interrupt Processing Initialization Succeeded.\n\r");
180	
181	    // init system call table
182	    init_syscall();
183	    printk("> [INIT] System Call Initialized Successfully.\n\r");
184	
185	    // init screen
186	    init_screen();
187	    printk("> [INIT] Screen Initialization Succeeded.\n\r");
188	
189	    // wakeup another core
190	    spin_lock_init(&kernel_lock);
191	    wakeup_other_hart();
192	    while(!smp_init_flag){
193	        ;
194	    }
195	    printk("> [INIT] Start the Second Core Successfully.\n\r");
196	    
197	    // Setup timer interrupt and enable all interrupt
198	    enable_interrupt();
199	    setup_exception();
200	    sbi_set_timer(get_ticks() + timer_interval);
201	
202	    while (1){
203	        disable_preempt();
204	        list_node_t* clean_node = kernel_pcb[0].wait_list.next;
205	        while(clean_node != &kernel_pcb[0].wait_list){
206	            pcb_t *clean_pcb = list_entry(clean_node, pcb_t, list);
207	            // release pcb
208	            clean_pcb->status = TASK_EXITED;
209	            clean_pcb->pid = -1;
210	            // release kernel stack
211	            free_user_page(kva2pa(clean_pcb->kernel_stack_base - PAGE_SIZE));
212	            
213	            clean_node = clean_node->next;
214	            list_del(clean_node->prev);
215	        }
216	    
217	        enable_preempt();
218	        __asm__ __volatile__("wfi\n\r":::);
219	    }
220	}

