72	/* start here */
73	int boot_kernel(unsigned long mhartid)
74	{
75	    if(mhartid == 0) {
76	        // setup memory mapping
77	        setup_vm();
78	        sbi_console_putstr("> [INIT] Set Up Kernel Page Table Successfully.\n\r");
79	        // load kernel
80	        start_kernel = (kernel_entry_t)load_elf(_elf_main, _length_main, PGDIR_PA, directmap);
81	        sbi_console_putstr("> [INIT] Copy Kernel to Memory Successfully.\n\r");
82	    }else {
83	        enable_vm();
84	    }
85	    start_kernel(mhartid);
86	    return 0;
87	}
